'use strict';
// Original, untimed play worlds. No external game art or child data is used.
const readingAdventureModes=new Set(['delivery-route','clue-rebuild','puppet-program']);
const readingDeliveryMissions=[
 {name:'The topsy-turvy picnic',intro:'Bear packed the picnic… but sent everything to the wrong street!',cargo:[['b','cup'],['d','spoon'],['b','apple']]},
 {name:'A very soggy Tuesday',intro:'The clouds are coming. Bring the neighbours their rainy-day surprises.',cargo:[['d','umbrella'],['b','boot'],['d','hat']]},
 {name:'The smallest toy parade',intro:'A parade is coming through town. Who ordered a very small train?',cargo:[['b','train'],['d','ball'],['d','teddy-bear']]}
];
const readingMysteries=[
 {name:'The missing kite',letter:'p',object:'kite',place:'tree',story:'A kite vanished! Its owner left a torn letter tag. Find both pieces to open the lost-property nook.'},
 {name:'The midnight picnic',letter:'q',object:'banana',place:'tent',story:'Someone borrowed the picnic snack. Two pieces of a torn tag will open the picnic tent.'},
 {name:'The runaway sock',letter:'p',object:'sock',place:'pond',story:'One sock has gone on holiday. Find the torn tag and discover its hiding place.'}
];
const readingMysteryClues=[{tree:'stem',tent:'bowl'},{pond:'stem',rock:'bowl'},{tent:'stem',pond:'bowl'}];
const readingPuppetScripts=[['b','d'],['d','b','d'],['p','q']];
const readingPuppetActions={b:'bounce',d:'duck',p:'pop up',q:'quiet'};
function readingAdventurePrepare(){const s=readingState,mode=readingGame(s.id).mode;if(!readingAdventureModes.has(mode))return false;s.word=null;s.adventureFocus=null;
 if(mode==='delivery-route')s.mission={loaded:null,delivered:[],where:'depot',gag:false};
 if(mode==='clue-rebuild')s.mystery={found:[],looked:[],selected:null,stem:null,gag:false};
 if(mode==='puppet-program'){s.show={slots:readingPuppetScripts[s.round].map(()=>null),selected:null,actor:s.show?.actor||'bear',action:'wave'};}
 return true;
}
function readingAdventureCue(){const s=readingState,g=readingGame(s.id);if(!readingAdventureModes.has(g.mode))return null;
 if(g.mode==='delivery-route')return `${g.adult} Any parcel can go first. Its address must match the door. Tap a parcel to load it, then a door; or drag the parcel to the van or door. A wrong address keeps the cargo safe.`;
 if(g.mode==='clue-rebuild')return `${g.adult} Today’s tag is ${readingMysteries[s.round].letter}. Explore the places in any order; the clues change hiding places. Move the descending stem to the matching side of the bowl. The model stays visible; locating clues is not a reading assessment.`;
 return `${g.adult} The visible script is ${readingPuppetScripts[s.round].join(', ')}. b runs bounce, d runs duck, p runs pop up and q runs quiet. These are game commands, not a lesson in isolated letter sounds. The legend stays visible.`;
}
function readingAdventureSvg(body,label,view='0 0 700 380'){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${view}" role="img" aria-label="${readingEscape(label)}">${body}</svg>`;}
function readingAdventureAnimal(kind='bear',action='wave',accessory=false){const duck=kind==='duck',down=action==='duck',quiet=action==='quiet';return readingAdventureSvg(`<ellipse cx="100" cy="175" rx="68" ry="10" fill="#233c42" opacity=".12"/><g transform="translate(0 ${down?36:action==='bounce'?-20:0})${down?' scale(1 .78)':''}">${duck?'':`<circle cx="56" cy="56" r="22" fill="#aa6b43"/><circle cx="142" cy="56" r="22" fill="#aa6b43"/><circle cx="56" cy="56" r="11" fill="#edbb8b"/><circle cx="142" cy="56" r="11" fill="#edbb8b"/>`}<ellipse cx="100" cy="134" rx="46" ry="41" fill="${duck?'#f2ce63':'#b97a50'}"/><path d="M68 156L57 174M128 156L142 174" stroke="${duck?'#d99039':'#a56842'}" stroke-width="18" stroke-linecap="round"/><path d="M64 121L${action==='wave'?37:49} ${action==='wave'?83:139}M137 118L156 132" stroke="${duck?'#e9ba43':'#b97a50'}" stroke-width="16" stroke-linecap="round"/><ellipse cx="100" cy="78" rx="52" ry="46" fill="${duck?'#ffe28a':'#cf9665'}"/><ellipse cx="99" cy="96" rx="27" ry="20" fill="${duck?'#ed9b3b':'#f4d6a9'}"/>${quiet?'<path d="M72 74q7 6 14 0M116 74q7 6 14 0" stroke="#3d3432" fill="none" stroke-width="3"/>':'<circle cx="79" cy="73" r="4" fill="#3d3432"/><circle cx="122" cy="73" r="4" fill="#3d3432"/>'}${duck?'':`<path d="M92 88Q100 83 108 88L100 97Z" fill="#503b32"/><path d="M87 104q13 13 26 0" stroke="#684a3a" stroke-width="3" fill="none"/>`}${accessory?'<path d="M54 42L100 8L143 42Z" fill="#8666a9"/><circle cx="100" cy="9" r="8" fill="#f3c35b"/>':''}<path d="M75 118Q100 130 126 118L117 145H82Z" fill="#5c9397"/>${action==='pop up'?'<path d="M36 52l-15-8M160 51l15-8M99 22V8" stroke="#c38339" stroke-width="4" stroke-linecap="round"/>':''}</g>`,`${kind} ${action}`,'0 -20 200 220');}
function readingAdventureVan(){return readingAdventureSvg('<ellipse cx="118" cy="127" rx="94" ry="10" fill="#46534d" opacity=".16"/><path d="M18 42Q18 28 33 28H136V111H18Z" fill="#6d97c1"/><path d="M136 52H180L208 86V111H136Z" fill="#e8b34c"/><path d="M147 61H175L190 82H147Z" fill="#e3f4f6"/><rect x="38" y="44" width="74" height="46" rx="9" fill="#fff7d8"/><path d="M43 50l32 24 31-24" fill="none" stroke="#c78d4d" stroke-width="4"/><circle cx="59" cy="113" r="18" fill="#354f5a"/><circle cx="173" cy="113" r="18" fill="#354f5a"/><circle cx="59" cy="113" r="8" fill="#d3ddd6"/><circle cx="173" cy="113" r="8" fill="#d3ddd6"/><rect x="199" y="88" width="10" height="11" rx="3" fill="#fff4b3"/>','A little delivery van','0 0 230 145');}
function readingTownBackground(){return readingAdventureSvg('<rect width="700" height="380" rx="26" fill="#dceff2"/><circle cx="581" cy="54" r="29" fill="#ffe5a0"/><path d="M0 190Q130 92 288 183T700 146V380H0Z" fill="#c0d9ad"/><path d="M0 257Q175 173 336 254T700 238V380H0Z" fill="#a8ca93"/><path d="M0 331Q188 251 366 294T700 304" fill="none" stroke="#f1d6a1" stroke-width="57"/><path d="M130 287L122 173M551 302L562 176" stroke="#f1d6a1" stroke-width="35"/><path d="M325 0Q292 119 349 210T356 380" fill="none" stroke="#8bc8d7" stroke-width="45"/><path d="M304 285L390 299" stroke="#a87b52" stroke-width="57"/><path d="M302 275L394 289M300 297L391 311" stroke="#f4d7a3" stroke-width="6"/><g fill="#fffdf2"><ellipse cx="93" cy="51" rx="48" ry="16"/><ellipse cx="123" cy="43" rx="27" ry="20"/><ellipse cx="420" cy="63" rx="36" ry="12"/></g><g stroke="#58744c" stroke-width="7"><path d="M33 228v-49M664 235v-62"/></g><g fill="#74a77b"><circle cx="33" cy="166" r="31"/><circle cx="664" cy="157" r="37"/></g>','A village with a road, two homes and a bridge');}
function readingParcel(i){const s=readingState,m=readingDeliveryMissions[s.round],c=m.cargo[i];return `<button class="ra-parcel ${s.mission.loaded===i?'selected':''}" data-ra-parcel="${i}" aria-label="${c[1].replaceAll('-',' ')}, address ${c[0]}; load parcel" aria-pressed="${s.mission.loaded===i}"><span class="ra-object">${readingPicture(c[1])}</span><span class="ra-address">${readingPaint(c[0])}</span></button>`;}
function readingDeliveryView(result=false){const s=readingState,m=readingDeliveryMissions[s.round],a=s.mission;return `<div class="ra-quest-line"><span>${readingEscape(m.name)}</span><b aria-label="${a.delivered.length} of 3 deliveries">${a.delivered.length} / 3 delivered</b></div>${result?'':`<p class="ra-story">${m.intro}</p><p class="ra-instruction">${a.loaded===null?'Pick a parcel. You choose the route!':`Cargo address: ${readingPaint(m.cargo[a.loaded][0])}. Drive to that door.`}</p>`}<div class="ra-town ra-scene">${readingTownBackground()}${['b','d'].map((letter,i)=>`<button class="ra-home ra-home-${i}" data-ra-door="${letter}" aria-label="Deliver to door ${letter}"><span class="ra-roof"></span><span class="ra-window">${readingAdventureAnimal(i?'duck':'bear')}</span><span class="ra-door">${readingPaint(letter)}</span><span class="ra-porch">${a.delivered.filter(n=>m.cargo[n][0]===letter).map(n=>`<span class="ra-gift">${readingPicture(m.cargo[n][1])}</span>`).join('')}</span></button>`).join('')}<button id="raVan" class="ra-van ra-at-${a.where}" aria-label="${a.loaded===null?'Empty van. Pick a parcel first.':`Van loaded for ${m.cargo[a.loaded][0]}; drag to a door`}">${readingAdventureVan()}${a.loaded===null?'':`<span class="ra-van-address">${readingPaint(m.cargo[a.loaded][0])}</span>`}</button><button id="raTownDuck" class="ra-town-duck" aria-label="Wave to the duck on the bridge">${readingAdventureAnimal('duck',a.gag?'bounce':'wave',a.gag)}${a.gag?'<span class="ra-duck-bubble" aria-hidden="true">Ta-da!</span>':''}</button></div>${result?'':`<div class="ra-cargo" aria-label="Parcels at the depot">${m.cargo.map((_,i)=>a.delivered.includes(i)?`<span class="ra-parcel-arrived" aria-label="Parcel delivered">✓</span>`:readingParcel(i)).join('')}</div><p class="reading-small">Tap a parcel, then a door. Or drag a parcel to the van or a door. Try waving to the bridge duck!</p>`}`;}
function readingForestBackground(){return readingAdventureSvg('<rect width="700" height="380" rx="26" fill="#e0e9f2"/><circle cx="570" cy="53" r="30" fill="#fff2bc"/><path d="M0 208Q180 92 355 204T700 180V380H0Z" fill="#aec8aa"/><path d="M0 284Q170 206 343 298T700 270V380H0Z" fill="#91b38f"/><path d="M304 380Q402 259 349 198" stroke="#e3cc9c" stroke-width="40" fill="none"/><path d="M117 279V85" stroke="#9a754f" stroke-width="42"/><path d="M117 157L73 109M119 195L163 140" stroke="#9a754f" stroke-width="19"/><g fill="#648e71"><circle cx="82" cy="76" r="58"/><circle cx="150" cy="63" r="60"/><circle cx="119" cy="112" r="59"/></g><ellipse cx="507" cy="303" rx="110" ry="42" fill="#83bec9"/><path d="M453 301q29-15 56 0M519 320q31-13 57 0" stroke="#c6e6df" stroke-width="4" fill="none"/><path d="M430 229L525 107L620 229Z" fill="#d7a275"/><path d="M483 229L525 157L567 229Z" fill="#6f775e"/><path d="M383 150q-28-43-55-1q-22-11-30 10" stroke="#dcdacc" stroke-width="12" fill="none"/><ellipse cx="152" cy="303" rx="45" ry="24" fill="#648767"/><circle cx="198" cy="305" r="14" fill="#bdca93"/><path d="M192 303q5 4 10 0" fill="none" stroke="#4c664d" stroke-width="2"/><path d="M125 309l-8 13M170 309l9 13" stroke="#bdca93" stroke-width="9" stroke-linecap="round"/><g fill="#f5dca0"><circle cx="268" cy="265" r="6"/><circle cx="283" cy="256" r="7"/><circle cx="297" cy="267" r="6"/></g>','A woodland mystery: tree, tent, pond and a sleepy rock');}
function readingMysteryView(result=false){const s=readingState,m=readingMysteries[s.round],a=s.mystery;const hotspots=[['tree','Tree hollow'],['tent','Picnic tent'],['pond','Pond ripples'],['rock','Sleepy rock']].map(([id,name])=>[id,name,readingMysteryClues[s.round][id]||null]);
 if(result)return `<div class="ra-reveal"><div class="ra-reveal-object">${readingPicture(m.object)}</div>${readingAdventureAnimal('duck','wave',true)}<p>Found in the ${m.place}! Duck was keeping it safe.</p></div>`;
 return `<div class="ra-quest-line"><span>${m.name}</span><b>${a.found.length} / 2 clues</b></div><p class="ra-story">${m.story}</p><div class="ra-forest ra-scene">${readingForestBackground()}${hotspots.map(([id,name,piece],i)=>`<button class="ra-hotspot ra-hotspot-${i} ${a.looked.includes(id)?'visited':''}" data-ra-search="${id}" aria-label="Explore ${name}"><span>${piece&&a.found.includes(piece)?'✓':'?'}</span><small>${name}</small></button>`).join('')}${a.gag?`<span class="ra-pond-duck">${readingAdventureAnimal('duck','bounce',true)}</span>`:''}</div><div class="ra-notebook"><div class="ra-tag-model"><span>Owner’s tag</span><b>${readingPaint(m.letter)}</b></div><div class="ra-clue-work"><p>${a.found.length<2?'Explore the woods. The notebook keeps your clues.':'Both pieces found! Put the long stem beside the bowl to repair the tag.'}</p><div class="ra-clue-tray">${['stem','bowl'].map(part=>a.found.includes(part)?`<button data-ra-clue="${part}" class="ra-clue ${a.selected===part?'selected':''}" aria-label="${part==='stem'?'Long descending stem':'Rounded bowl'}; ${part==='stem'?'move to a side of the bowl':'inspect clue'}" aria-pressed="${a.selected===part}">${readingAdventureSvg(part==='stem'?'<path d="M35 18V114" stroke="#345b47" stroke-width="10" stroke-linecap="round"/>':'<ellipse cx="35" cy="45" rx="24" ry="28" fill="none" stroke="#345b47" stroke-width="10"/>',part,'0 0 70 130')}</button>`:`<span class="ra-clue-missing" aria-label="${part} not found yet">?</span>`).join('')}</div></div></div>${a.found.length===2?`<div class="ra-tag-repair"><button data-ra-stem="left" aria-label="Put the descending stem on the left of the bowl">Stem here</button><span class="ra-fixed-bowl">${readingAdventureSvg(`<ellipse cx="50" cy="42" rx="28" ry="29" fill="none" stroke="#345b47" stroke-width="10"/>${a.stem?`<path d="M${a.stem==='left'?22:78} 15V110" stroke="#345b47" stroke-width="10" stroke-linecap="round"/>`:''}`,'Rounded part stays here','0 0 100 120')}</span><button data-ra-stem="right" aria-label="Put the descending stem on the right of the bowl">Stem here</button></div><p class="reading-small">Drag the long stem to a side, or tap a “Stem here” space. Compare with the owner’s tag.</p>`:'<p class="reading-small">Tap a place, or drag the magnifier over it.</p>'}<button id="raMagnifier" class="ra-magnifier" aria-label="Magnifier; drag over a woodland place">${readingAdventureSvg('<circle cx="33" cy="31" r="22" fill="#cce9ec" fill-opacity=".8" stroke="#795a91" stroke-width="7"/><path d="M49 48L73 73" stroke="#bd8c50" stroke-width="13" stroke-linecap="round"/>','Magnifier','0 0 90 90')}</button>`;
}
function readingPuppetStage(action,actor,mini=false){const quiet=action==='quiet';return `<div class="ra-puppet-stage ${mini?'ra-mini-stage':''}">${readingAdventureSvg(`<rect width="700" height="300" rx="20" fill="${quiet?'#dce2f2':'#f7e5b5'}"/><path d="M0 0H100Q115 120 44 242H0ZM700 0H600Q585 120 656 242H700Z" fill="#b2768e"/><path d="M0 0Q85 80 175 0Q260 80 350 0Q435 80 525 0Q610 80 700 0" fill="#925571"/><path d="M25 264H675" stroke="#9a7555" stroke-width="45"/><g fill="#ffe9a8"><path d="M155 55l5 12 13 1-10 8 3 13-11-7-11 7 3-13-10-8 13-1Z"/><path d="M545 55l5 12 13 1-10 8 3 13-11-7-11 7 3-13-10-8 13-1Z"/></g>${action==='bounce'?'<path d="M270 230q-22-45 0-84M430 230q22-45 0-84" stroke="#b89057" stroke-width="5" stroke-dasharray="8 9" fill="none"/>':''}${action==='pop up'?'<path d="M280 240L266 166H433L418 240Z" fill="#729894"/><ellipse cx="350" cy="166" rx="84" ry="15" fill="#abc2aa"/>':''}`,`${quiet?'Moonlit':'Colourful'} puppet stage`)}<span class="ra-puppet">${readingAdventureAnimal(actor,action,true)}</span>${action==='pop up'?'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 700 300" aria-hidden="true" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"><path d="M273 196Q350 211 427 196L418 240H280Z" fill="#729894"/><path d="M273 196Q350 211 427 196" fill="none" stroke="#abc2aa" stroke-width="6"/></svg>':''}<span class="ra-stage-action">${readingPuppetActions[action]||'Ready for your show'}</span></div>`;}
function readingPuppetView(result=false){const s=readingState,a=s.show,target=readingPuppetScripts[s.round];if(result)return `<div class="ra-final-show">${target.map(action=>readingPuppetStage(action,a.actor,true)).join('')}</div>`;
 return `<div class="ra-quest-line"><span>You direct the puppet show</span><span class="ra-cast" role="group" aria-label="Choose your puppet">${['bear','duck'].map(actor=>`<button data-ra-actor="${actor}" aria-label="Choose ${actor} puppet" aria-pressed="${a.actor===actor}">${readingAdventureAnimal(actor)}</button>`).join('')}</span></div>${readingPuppetStage(a.action,a.actor)}<div class="ra-script"><span>The audience asks:</span><div>${target.map((v,i)=>`<span><b>${v}</b><small>${readingPuppetActions[v]}</small></span>`).join('<i aria-hidden="true">→</i>')}</div></div><p class="ra-instruction">Build their show. Each card makes your puppet do something!</p><div class="ra-show-slots" aria-label="Your show, in order">${a.slots.map((v,i)=>`<button data-ra-show-slot="${i}" class="${v?'filled':''}" aria-label="Scene ${i+1}${v?': '+v+', '+readingPuppetActions[v]+'. Tap to return card.':': empty. Drop a command here.'}">${v?`<b>${v}</b><small>${readingPuppetActions[v]}</small>`:`<span>${i+1}</span>`}</button>`).join('')}</div><div class="ra-command-bank" aria-label="Puppet commands">${['b','d','p','q'].map(v=>`<button data-ra-command="${v}" aria-label="Command ${v}: ${readingPuppetActions[v]}"><b>${v}</b><small>${readingPuppetActions[v]}</small></button>`).join('')}</div><p class="reading-small">Tap a card for the next space, or drag it to any scene. Tap a filled scene to return it; drag two scenes to swap them. The show finishes itself when the script fits.</p>`;
}
function readingAdventureChallenge(){const mode=readingGame(readingState.id).mode;if(!readingAdventureModes.has(mode))return null;const titles={'delivery-route':'Three parcels. One tiny van. Your route!','clue-rebuild':'A mystery is waiting in the woods…','puppet-program':'Lights up! You are the director.'};return `<div class="reading-adventure"><h2 class="reading-invitation" tabindex="-1">${titles[mode]}</h2>${mode==='delivery-route'?readingDeliveryView():mode==='clue-rebuild'?readingMysteryView():readingPuppetView()}</div>`;}
function readingAdventureResult(){const mode=readingGame(readingState.id).mode;const result=mode==='delivery-route'?readingDeliveryView(true):mode==='clue-rebuild'?readingMysteryView(true):mode==='puppet-program'?readingPuppetView(true):null;return result===null?null:result.replaceAll('<button ','<button disabled tabindex="-1" ');}
function readingAdventureMessage(){const s=readingState,mode=readingGame(s.id).mode;return mode==='delivery-route'?'Special delivery! Everyone is ready for the adventure.':mode==='clue-rebuild'?`Mystery solved! You repaired the ${readingMysteries[s.round].letter} tag.`:mode==='puppet-program'?'Bravo! Your letters brought the puppet show to life.':null;}
function readingAdventureRefresh(focus){readingState.adventureFocus=focus||null;readingRender();}
function readingDeliveryLoad(index){if(!readingCanAct()||readingGame(readingState.id).mode!=='delivery-route')return;const a=readingState.mission;if(a.delivered.includes(index)||!readingDeliveryMissions[readingState.round].cargo[index])return;a.loaded=index;readingState.message='Loaded! Choose a door on the map.';readingAdventureRefresh('[data-ra-door]');}
function readingDeliveryDoor(letter,index){if(!readingCanAct()||readingGame(readingState.id).mode!=='delivery-route')return;const s=readingState,a=s.mission,m=readingDeliveryMissions[s.round];const chosen=index===undefined?a.loaded:index;if(chosen===null||a.delivered.includes(chosen)||!m.cargo[chosen]){s.message='The van needs a parcel. Pick any one from the depot.';readingAdventureRefresh('[data-ra-parcel]');return;}a.loaded=chosen;a.where=letter;if(m.cargo[chosen][0]!==letter){s.message=`This door says ${letter}. Your parcel says ${m.cargo[chosen][0]}. Keep driving—your parcel is safe!`;readingAdventureRefresh(`[data-ra-door="${m.cargo[chosen][0]}"]`);return;}a.delivered.push(chosen);a.loaded=null;s.message=`Delivered the ${m.cargo[chosen][1].replaceAll('-',' ')}! The neighbours are delighted.`;if(a.delivered.length===m.cargo.length)readingSuccess('delivery-mission');else readingAdventureRefresh('[data-ra-parcel]');}
function readingMysterySearch(place){if(!readingCanAct()||readingGame(readingState.id).mode!=='clue-rebuild')return;const s=readingState,a=s.mystery;if(!['tree','tent','pond','rock'].includes(place))return;if(!a.looked.includes(place))a.looked.push(place);const part=readingMysteryClues[s.round][place];if(part){if(!a.found.includes(part))a.found.push(part);s.message=a.found.length===2?'Both clues found! Repair the tag in the notebook below.':part==='stem'?'A long descending stem! It goes into your notebook.':'A rounded bowl! Keep it with the other clue.';}else{a.gag=!a.gag;s.message=place==='pond'?'Duck is practising a very wobbly water ballet. No clue here!':'That “rock” just snored. Better let the tortoise sleep.';}readingAdventureRefresh(a.found.length===2?'[data-ra-stem]':`[data-ra-search="${place}"]`);}
function readingMysteryStem(side){if(!readingCanAct()||readingGame(readingState.id).mode!=='clue-rebuild')return;const s=readingState,a=s.mystery,m=readingMysteries[s.round];if(a.found.length!==2||!['left','right'].includes(side))return;a.stem=side;const correct=m.letter==='p'?'left':'right';if(side!==correct){s.message=`That makes ${side==='left'?'p':'q'}. Compare the long stem with the ${m.letter} tag. You can move it.`;readingAdventureRefresh(`[data-ra-stem="${correct}"]`);return;}readingSuccess('reconstructed-clue');}
function readingPuppetPlace(command,index){if(!readingCanAct()||readingGame(readingState.id).mode!=='puppet-program'||!Object.hasOwn(readingPuppetActions,command))return;const s=readingState,a=s.show;let i=index===undefined?a.slots.indexOf(null):index;if(i<0||i>=a.slots.length){s.message='Your show is full. Tap a scene to change its card, or swap two scenes.';readingAdventureRefresh('[data-ra-show-slot]');return;}a.slots[i]=command;a.action=command;readingPuppetCheck();}
function readingPuppetCheck(){const s=readingState,a=s.show,target=readingPuppetScripts[s.round];if(a.slots.every((v,i)=>v===target[i])){readingSuccess('programmed-show');return;}const full=a.slots.every(Boolean);s.message=full?'Your puppet tried that show! Compare the audience’s script. Tap a card to change it, or swap scenes.':`Your puppet can ${readingPuppetActions[a.action]}. What happens next?`;readingAdventureRefresh(full?'[data-ra-show-slot]':'[data-ra-command]');}
function readingAdventureBind(){const s=readingState,g=readingGame(s.id);if(!readingAdventureModes.has(g.mode))return;const round=s.round;const bind=(el,d)=>{if(el&&!s.done&&typeof TouchPlay!=='undefined'){const drop=d.drop;TouchPlay.bind(el,{...d,drop:target=>{if(readingActive(s)&&s.round===round&&readingCanAct())drop(target);}});}};
 if(!s.done){
 app.querySelectorAll('[data-ra-parcel]').forEach(el=>{const i=+el.dataset.raParcel;el.onclick=()=>readingDeliveryLoad(i);bind(el,{targets:()=>[...app.querySelectorAll('#raVan,[data-ra-door]')],drop:target=>target.id==='raVan'?readingDeliveryLoad(i):readingDeliveryDoor(target.dataset.raDoor,i)});});
 app.querySelectorAll('[data-ra-door]').forEach(el=>el.onclick=()=>readingDeliveryDoor(el.dataset.raDoor));const van=app.querySelector('#raVan');if(van){van.onclick=()=>{if(!readingCanAct())return;s.message=s.mission.loaded===null?'Pick a parcel to load the van.':'Ready to drive! Tap a door, or drag the van there.';readingAdventureRefresh(s.mission.loaded===null?'[data-ra-parcel]':'[data-ra-door]');};bind(van,{targets:()=>[...app.querySelectorAll('[data-ra-door]')],drop:el=>readingDeliveryDoor(el.dataset.raDoor)});}
 const duck=app.querySelector('#raTownDuck');if(duck)duck.onclick=()=>{if(!readingCanAct())return;s.mission.gag=!s.mission.gag;s.message=s.mission.gag?'Duck says: special delivery… one enormous quack!':'Duck waves you on. The bridge is clear.';readingAdventureRefresh('#raTownDuck');};
 app.querySelectorAll('[data-ra-search]').forEach(el=>el.onclick=()=>readingMysterySearch(el.dataset.raSearch));bind(app.querySelector('#raMagnifier'),{targets:()=>[...app.querySelectorAll('[data-ra-search]')],drop:el=>readingMysterySearch(el.dataset.raSearch)});
 app.querySelectorAll('[data-ra-stem]').forEach(el=>el.onclick=()=>readingMysteryStem(el.dataset.raStem));app.querySelectorAll('[data-ra-clue]').forEach(el=>{const part=el.dataset.raClue;el.onclick=()=>{if(!readingCanAct())return;s.mystery.selected=part;s.message=part==='stem'?'Choose a side of the bowl for the long stem.':'The bowl is rounded. The stem will join it on one side.';readingAdventureRefresh('[data-ra-stem]');};if(part==='stem')bind(el,{targets:()=>[...app.querySelectorAll('[data-ra-stem]')],drop:target=>readingMysteryStem(target.dataset.raStem)});});
 app.querySelectorAll('[data-ra-actor]').forEach(el=>el.onclick=()=>{if(!readingCanAct())return;s.show.actor=el.dataset.raActor;readingAdventureRefresh(`[data-ra-actor="${s.show.actor}"]`);});
 app.querySelectorAll('[data-ra-command]').forEach(el=>{const command=el.dataset.raCommand;el.onclick=()=>readingPuppetPlace(command);bind(el,{targets:()=>[...app.querySelectorAll('[data-ra-show-slot]')],drop:target=>readingPuppetPlace(command,+target.dataset.raShowSlot)});});
 app.querySelectorAll('[data-ra-show-slot]').forEach(el=>{const i=+el.dataset.raShowSlot;el.onclick=()=>{if(!readingCanAct())return;s.show.slots[i]=null;s.message='Scene returned. Choose another command.';readingAdventureRefresh(`[data-ra-show-slot="${i}"]`);};if(s.show.slots[i])bind(el,{targets:()=>[...app.querySelectorAll('[data-ra-show-slot]')],drop:target=>{if(!readingCanAct())return;const j=+target.dataset.raShowSlot;[s.show.slots[i],s.show.slots[j]]=[s.show.slots[j],s.show.slots[i]];readingPuppetCheck();}});});
 }
 const focus=s.adventureFocus;s.adventureFocus=null;if(focus)app.querySelector(focus)?.focus({preventScroll:true});
}
